<?php
require __DIR__.'/Support/OemDisposable.php';require __DIR__.'/Support/OemFixtures.php';
use think\facade\Db;
use app\common\service\virtualpay\VirtualPayConfigService as Config;
use app\common\service\virtualpay\VirtualPayPolicy as Policy;
use app\common\service\virtualpay\VirtualPaySessionService as Session;
use app\common\service\virtualpay\VirtualPayGateway as Gateway;
Db::startTrans();try{
 $t=Db::name('tenant')->insertGetId(['sn'=>'vpay-test-'.random_int(10000,99999),'name'=>'Virtual config','create_time'=>time()]);
 request()->tenantId=$t;request()->source=app\common\enum\AdminTerminalEnum::PLATFORM;
 Db::name('tenant_config')->insert(['tenant_id'=>$t,'type'=>'mnp_setting','name'=>'app_id','value'=>'wxvirtual-test']);
 Db::name('tenant_config')->insert(['tenant_id'=>$t,'type'=>'mnp_setting','name'=>'app_secret','value'=>'fixture-secret']);
 $u=Db::name('user')->insertGetId(['tenant_id'=>$t,'sn'=>random_int(100000,999999),'account'=>'virtual-test','create_time'=>time()]);
 Db::name('user_auth')->insert(['tenant_id'=>$t,'user_id'=>$u,'terminal'=>1,'openid'=>'fixture-openid','create_time'=>time()]);
 $d=Config::detail($t,0);oemCheck($d['enabled']===0&&$d['app_id']==='wxvirtual-test','effective app and disabled default');
 oemReject(fn()=>Config::save($t,0,['enabled'=>1,'app_id'=>'wxOTHER','offer_id'=>'123','app_key'=>'abc']),'no client-selected app');
 $d=Config::save($t,0,['enabled'=>1,'offer_id'=>'123','app_key'=>'fixture-private-appkey','token'=>'fixture-token','aes_key'=>str_repeat('A',43),'message_mode'=>'safe']);
 oemCheck($d['key_configured']&&!isset($d['app_key'])&&!str_contains(json_encode($d),'fixture-private-appkey'),'no secret echo');
 $first=Config::active($t,0);$d=Config::save($t,0,['enabled'=>1,'offer_id'=>'123','app_key'=>'']);$latest=Config::active($t,0);
 oemCheck(Config::secret($latest,'app_key')==='fixture-private-appkey','blank keeps key');
 Config::save($t,0,['enabled'=>1,'offer_id'=>'124','app_key'=>'new-private-appkey']);
 oemCheck(Config::secret(Config::version($t,(int)$first['id']),'app_key')==='fixture-private-appkey','old merchant remains available');
 oemReject(fn()=>Config::version($t+1,(int)$first['id']),'no cross tenant version');
 Db::name('tenant_config')->where(['tenant_id'=>$t,'type'=>'mnp_setting','name'=>'app_id'])->update(['value'=>'wxNEW-app']);
 oemCheck(Config::detail($t,0)['enabled']===0,'app switch never reuses key');
 Db::name('tenant_config')->where(['tenant_id'=>$t,'type'=>'mnp_setting','name'=>'app_id'])->update(['value'=>'wxvirtual-test']);
 $fake=new Gateway(static fn($method,$path,$query,$body)=>['openid'=>'fixture-openid','session_key'=>'fixture-session']);
 $session=new Session($fake);$sid=$session->exchange($t,$u,'code');$secret=$session->get($t,$u,'wxvirtual-test',$sid);
 oemCheck($secret['openid']==='fixture-openid'&&!str_contains($sid,'fixture-session'),'bound encrypted session');
 oemReject(fn()=>$session->get($t,$u+1,'wxvirtual-test',$sid),'session user isolation');
 oemReject(fn()=>$session->get($t,$u,'wx-other',$sid),'session app isolation');
 $wrong=new Session(new Gateway(static fn()=>['openid'=>'someone-else','session_key'=>'secret']));oemReject(fn()=>$wrong->exchange($t,$u,'wrong-code'),'code cannot pay for another authenticated identity');
 $sign=Policy::sign(['offerId'=>'124','buyQuantity'=>1,'env'=>0,'currencyType'=>'CNY','productId'=>'regular-month','goodsPrice'=>1900,'outTradeNo'=>'V123456789','attach'=>'intent'], 'new-private-appkey','fixture-session');
 oemCheck($sign['paySig']===hash_hmac('sha256','requestVirtualPayment&'.$sign['signData'],'new-private-appkey'),'raw signData bytes');
 oemCheck($sign['signature']===hash_hmac('sha256',$sign['signData'],'fixture-session'),'session signature');
 oemReject(fn()=>Policy::client('ios',1,990),'iOS rejects sandbox');oemReject(fn()=>Policy::client('ios',0,99),'iOS minimum');Policy::client('android',1,1);
 $pkg=app\common\service\recharge\RechargePackageService::save($t,['name'=>'Virtual goods','amount'=>'19.00','points'=>'100']);
 Config::saveProduct($t,0,['from'=>'recharge','package_id'=>$pkg->id,'cycle'=>'package','variant'=>'regular','product_id'=>'regular-month','price'=>'19.00']);
 $g=Config::product($t,'wxvirtual-test',0,'recharge',$pkg->id,'package','regular');oemCheck($g['price_cents']===1900,'price mapping in fen');
 oemReject(fn()=>Config::saveProduct($t,0,['from'=>'recharge','package_id'=>$pkg->id,'cycle'=>'package','variant'=>'regular','product_id'=>'bad','price'=>'9.90']),'mapping must match backend price');
 $calls=[];$transport=new Gateway(static function($method,$path,$query,$body)use(&$calls){$calls[]=[$method,$path,$query,$body];return ['errcode'=>0,'order'=>[]];});
 $version=Config::active($t,0);$transport->request($version,'/xpay/query_order',['openid'=>'fixture-openid','env'=>0,'order_id'=>'V123456789']);
 $call=$calls[0];oemCheck($call[2]['pay_sig']===hash_hmac('sha256','/xpay/query_order&'.$call[3],'new-private-appkey'),'outgoing query signs actual raw body including leading slash');
 Config::save($t,1,['enabled'=>1,'offer_id'=>'999','app_key'=>'fixture-sandbox-appkey']);
 oemCheck(Config::active($t,1)['offer_id']==='999'&&Config::active($t,0)['offer_id']==='124','sandbox cannot overwrite production credentials');
 oemReject(fn()=>Config::product($t,'wxvirtual-test',1,'recharge',$pkg->id,'package','regular'),'no cross environment product fallback');
 oemCheck(!str_contains(Db::name('virtual_pay_config_version')->where('id',$version['id'])->value('app_key'),'new-private-appkey'),'ciphertext persisted');
 app\common\service\billing\PackageProvisionService::syncTenant($t);
 app\common\service\billing\PackageProvisionService::syncTenant($t);
 oemCheck(Db::name('tenant_system_menu')->where(['tenant_id'=>$t,'source_menu_key'=>'core_tenant_virtual_pay'])->count()===1,'runtime menu sync is repeatable');
 oemCheck(Db::name('tenant_system_menu')->where(['tenant_id'=>$t,'perms'=>'finance.promotion/detail'])->count()===1,'promotion read permission initialized');
 echo "PASS app/env isolation, encrypted key versions, bound sessions, raw HMAC and goods amounts\n";
}finally{Db::rollback();}
